$('#icsFile').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;const txt=(await f.text()).replace(/\r?\n[ \t]/g,'');let count=0,skipped=0;for(const block of txt.split('BEGIN:VEVENT').slice(1)){const lines=block.split(/\r?\n/),get=n=>lines.find(l=>l.startsWith(n+':')||l.startsWith(n+';'));const start=get('DTSTART'),end=get('DTEND'),title=get('SUMMARY');if(lines.some(l=>/^(RRULE|RECURRENCE-ID)/.test(l))||/TZID=/.test(start||'')||!start||!title){skipped++;continue}const st=icsDate(start.slice(start.indexOf(':')+1)),en=end?icsDate(end.slice(end.indexOf(':')+1)):new Date(+st+86400000),name=title.slice(title.indexOf(':')+1).replace(/\\n/g,' ').replace(/\\([,;\\])/g,'$1');try{validateEvent(name,st,en);if(events.some(e=>e.title===name&&+new Date(e.start)===+st))continue;events.push({id:crypto.randomUUID(),title:name,start:st.toISOString(),end:en.toISOString(),scene:/运动|健身|跑步/.test(name)?'energy':/睡|休息/.test(name)?'relax':'focus'});count++}catch{skipped++}}save('events',events);renderEvents();render();ev.target.value='';toast(`已导入 ${count} 项，跳过 ${skipped} 项（重复规则、命名时区或格式不支持）`)};
function timerDialog(kind){const focus=kind==='focus',end=focus?focusEnd:sleepEnd;modal(focus?'留一段专注时间':'让音乐陪你入眠',`<p class="muted">${focus?'选择一段不被打扰的时间。结束时会在页面内提醒你。':'到时将缓缓降低音量并停止播放。请保持页面打开。'}</p>${end?'<p>正在计时：剩余 '+Math.max(0,Math.ceil((end-Date.now())/60000))+' 分钟</p>':''}<div class="time-options">${(focus?[15,25,45,60]:[15,30,45,60,90]).map(n=>`<button data-minutes="${n}">${n} 分钟</button>`).join('')}</div><button class="text-button" id="cancelTimer">取消${focus?'专注':'睡眠'}计时</button><p class="muted small">浏览器暂停或设备休眠时可能延迟执行；回到页面后会检查到期状态。</p>`);$$('[data-minutes]').forEach(b=>b.onclick=()=>{const n=+b.dataset.minutes;if(focus){focusEnd=Date.now()+n*60000;selectScene('focus',true)}else{clearInterval(fadeInterval);sleepEnd=Date.now()+n*60000;selectScene('sleep',true)}$('#dialog').close();toast(`${focus?'专注':'睡眠'}计时已开启：${n} 分钟`);tick()});$('#cancelTimer').onclick=()=>{if(focus)focusEnd=0;else{sleepEnd=0;clearInterval(fadeInterval);audio.volume=+$('#volume').value}$('#dialog').close();tick();toast('计时已取消')}}$('#focusBtn').onclick=()=>timerDialog('focus');$('#sleepBtn').onclick=()=>timerDialog('sleep');
let lastSchedule=null;function tick(){const now=Date.now();if(focusEnd&&now>=focusEnd){focusEnd=0;toast('这一段专注结束了，起来活动一下吧');message('assistant','专注时间到了。辛苦啦，给眼睛和身体一点休息。')}if(sleepEnd&&now>=sleepEnd){sleepEnd=0;let vol=audio.volume;clearInterval(fadeInterval);fadeInterval=setInterval(()=>{vol=Math.max(0,vol-.035);audio.volume=vol;if(vol===0){audio.pause();clearInterval(fadeInterval);audio.volume=+$('#volume').value;toast('睡眠计时结束。晚安。')}},140)}$('#focusHint').textContent=focusEnd?'专注中 · '+fmt(Math.max(0,(focusEnd-now)/1000)):'25 分钟，只做眼前这一件事';$('#sleepHint').textContent=sleepEnd?'将在 '+Math.ceil((sleepEnd-now)/60000)+' 分钟后停止':'到时间，声音会轻轻停下';const ev=events.find(e=>+new Date(e.start)<=now&&+new Date(e.end)>now);if(ev&&ev.id!==lastSchedule){lastSchedule=ev.id;selectScene(ev.scene,true)}if(!ev)lastSchedule=null}setInterval(tick,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});
function weatherLabel(code){return code===0?'晴朗':code<=3?'多云':code<=48?'雾':code<=67?'雨':code<=77?'雪':code<=82?'阵雨':code<=86?'阵雪':'雷雨'}
function showWeather(){if(weather)$('#weatherText').textContent=weather.city+' · '+Math.round(weather.temp)+'° '+weather.label+(Date.now()-weather.at>3600000?'（已缓存）':'');}showWeather();
async function fetchWeather(city,lat,lon){try{const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,weather_code&timezone=auto`,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('天气服务暂不可用');const d=await r.json();if(!d.current)throw Error('未取得天气数据');weather={city,lat,lon,temp:d.current.temperature_2m,label:weatherLabel(d.current.weather_code),at:Date.now()};save('weather',weather);showWeather();render();if($('#dialogTitle').textContent==='选择你的城市')$('#dialog').close();toast('已更新'+city+'天气')}catch(e){toast('天气查询失败，请稍后重试')}}
$('#weatherBtn').onclick=()=>{modal('选择你的城市',`<p class="muted">输入城市查询天气，或授权本次定位。${weather?'上次更新：'+esc(new Date(weather.at).toLocaleString('zh-CN')):''}</p><form id="cityForm"><input id="cityInput" placeholder="例如 Shanghai / 北京" required aria-label="城市名称"><button class="primary">搜索城市</button><button type="button" class="secondary" id="locate">使用当前位置</button></form><div id="cityResults"></div>`);$('#cityForm').onsubmit=async e=>{e.preventDefault();const q=$('#cityInput').value.trim();$('#cityResults').textContent='正在查找…';try{const r=await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(q)+'&count=5&language=zh&format=json',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();const d=await r.json();$('#cityResults').innerHTML=(d.results||[]).map((c,i)=>`<div class="queue-item"><button data-city="${i}">${esc(c.name)} · ${esc(c.admin1||'')} · ${esc(c.country||'')}</button></div>`).join('')||'没找到城市，试试拼音或英文名称。';$$('[data-city]').forEach(b=>b.onclick=()=>{const c=d.results[+b.dataset.city];fetchWeather(c.name,c.latitude,c.longitude)})}catch{$('#cityResults').textContent='城市查询失败，请检查网络后重试。'}};$('#locate').onclick=()=>{if(!navigator.geolocation)return toast('浏览器不支持定位，请手动选择城市');navigator.geolocation.getCurrentPosition(p=>fetchWeather('当前位置',p.coords.latitude,p.coords.longitude),()=>toast('未获得位置，请手动选择城市'),{timeout:10000})}};
function message(role,text){const el=document.createElement('div');el.className='message '+role;const bubble=document.createElement('div');bubble.className='message-bubble';const label=document.createElement('span');label.className='message-label';label.textContent=role==='user'?'我':'声屿 Agent';if(role!=='user'){const b=document.createElement('button');b.type='button';b.dataset.readMessage='';b.setAttribute('aria-label','朗读这条回复');b.innerHTML=soundIcon('volume');label.append(b)}const p=document.createElement('p');p.textContent=text;bubble.append(label,p);const time=document.createElement('time');time.textContent=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});el.append(bubble,time);$('#messages').append(el);$('#messages').scrollTop=$('#messages').scrollHeight;return el}
function speak(text){if(!prefs.voiceOut||!window.speechSynthesis)return;window.speechSynthesis.cancel();const wasVolume=+$('#volume').value;audio.volume=Math.min(.15,wasVolume);const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=.95;u.onend=u.onerror=()=>audio.volume=+$('#volume').value;window.speechSynthesis.speak(u)}
async function llmCall(config,messages,options={}){const r=await fetch(config.endpoint+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json',...(config.key?{Authorization:'Bearer '+config.key}:{})},body:JSON.stringify({model:config.model,messages,...options}),signal:AbortSignal.timeout(35000)});if(!r.ok)throw Error('模型服务返回 '+r.status+'，请检查地址、模型与密钥');const data=await r.json();const text=data.choices?.[0]?.message?.content;if(typeof text!=='string'||!text.trim())throw Error('模型返回了无法识别的回复');return text}
$('#connectLLM').onclick=async()=>{const b=$('#connectLLM');b.disabled=true;b.textContent='正在验证…';try{const c={endpoint:safeEndpoint($('#llmEndpoint').value.trim()),model:$('#llmModel').value.trim(),key:$('#llmKey').value};if(!c.model)throw Error('请填写模型名称');await llmCall(c,[{role:'user',content:'Reply only with OK.'}],{max_tokens:16});llm=c;save('llmEndpoint',c.endpoint);save('llmModel',c.model);$('#llmStatus').textContent='已连接 · '+c.model;$('#chatMode').textContent='已连接模型 · '+c.model;toast('模型连接成功，可以开始聊天')}catch(e){toast('连接失败：'+e.message+'。服务需支持浏览器跨域访问。')}finally{b.disabled=false;b.textContent='连接并验证'}};$('#disconnectLLM').onclick=()=>{llm=null;$('#llmKey').value='';$('#llmStatus').textContent='未连接';$('#chatMode').textContent='本机指令演示 · 尚未连接 LLM';toast('模型已断开')};
async function runAction(a){if(!a||!a.type||a.type==='none')return '';switch(a.type){case 'scene':if(!sceneData.some(s=>s.id===a.scene))throw Error('无法识别该音乐场景');await selectScene(a.scene,true);return prefs.switchMode==='suggest'?'已给出场景建议，由你决定是否应用。':pendingScene?'已调整场景，当前歌曲结束后更新音乐。':audio.paused?'已调整场景，播放尚未开始，请点击播放。':'场景已调整，音乐正在播放。';case 'ambient':if(!window.soundAmbient)throw Error('声景尚未就绪');window.soundAmbient.set(a.mix);return audio.paused?'声景比例已调整，将在开始播放时生效。':'声景比例已调整。';case 'preference':if(!['ambient','piano','electronic','all'].includes(a.genre))throw Error('偏好参数无效');prefs.genre=a.genre;$('#genre').value=a.genre;save('prefs',prefs);await selectScene(scene,true);return pendingScene?'已调整偏好，当前歌曲结束后应用推荐。':'已调整音乐偏好。';case 'pause':audio.pause();return '音乐已暂停。';case 'play':return await startPlay()?'音乐已开始播放。':'音乐尚未开始，请点击播放按钮重试。';case 'next':await next();return audio.paused?'未能开始下一首，请检查音源。':'已播放下一首：'+current.title+'。';case 'volume':if(!Number.isFinite(a.value))throw Error('音量参数无效');audio.volume=Math.min(1,Math.max(0,a.value));$('#volume').value=audio.volume;return '音量已调整。';case 'focus':if(!(a.minutes>=1&&a.minutes<=240))throw Error('专注时长需在 1—240 分钟内');focusEnd=Date.now()+a.minutes*60000;await selectScene('focus',true);return '已开启 '+a.minutes+' 分钟专注计时。';case 'sleep':if(!(a.minutes>=1&&a.minutes<=240))throw Error('睡眠时长需在 1—240 分钟内');sleepEnd=Date.now()+a.minutes*60000;await selectScene('sleep',true);return '已设置 '+a.minutes+' 分钟后停止播放。';default:throw Error('暂不支持这项操作')}}
async function sendChat(text){text=text.trim();if(!text||busy)return;busy=true;$('#send').disabled=true;message('user',text);chatHistory.push({role:'user',content:text});const pending=message('assistant','正在听你说…');try{let reply,action;if(llm){const system=`你是声屿，一位温暖、有分寸的音乐伴侣。用简短中文回应，不诊断，不编造已经执行的结果。你可以提议一个操作，真实执行结果由应用另行展示。当前场景=${scene}，当前歌曲=${current.title}，正在播放=${!audio.paused}。音乐列表=${allTracks().map(t=>t.title).join('、')}。请严格输出JSON：{"reply":"对用户的自然回复","action":{"type":"none"}}。允许的action：scene(附scene=relax|focus|energy|sleep)、play、pause、next、volume(附value=0到1)、focus或sleep(附minutes=1到240)。还允许ambient(附mix对象，键rain|waves|fire|wind|cafe，值0到1)、preference(附genre=piano|ambient|electronic|all)。用户只是倾诉且未明显需要换场景时用none。不要声称已执行动作。`;const raw=await llmCall(llm,[{role:'system',content:system},...chatHistory.slice(-12)]);let parsed;try{parsed=JSON.parse(raw.replace(/^```(?:json)?\s*/,'').replace(/\s*```$/,''))}catch{throw Error('模型未返回有效的操作格式，本次没有执行指令。请换一种说法重试')}if(typeof parsed.reply!=='string')throw Error('模型回复缺少内容');reply=parsed.reply;action=parsed.action}else{reply='这是本机指令演示。连接模型后，我就能更自然地听你说话。';action={type:'none'};const minutes=Number(text.match(/(\d+)\s*分钟/)?.[1]);if(/暂停|停一下|别放了/.test(text)){reply='好，给你留一点安静。';action={type:'pause'}}else if(/下一首|换一首/.test(text)){reply='试试另一个声音。';action={type:'next'}}else if(/雨声/.test(text)){reply='可以，调整这层自然声景。';action={type:'ambient',mix:{rain:/去掉|关闭|不要/.test(text)?0:.55}}}else if(/钢琴/.test(text)){reply='优先选择器乐与钢琴，留一点安静。';action={type:'preference',genre:'piano'}}else if(/轻柔|轻一点|太吵|不要鼓|去掉节拍/.test(text)){reply='把音量放轻一点。原曲的乐器不会被移除，你可以继续选择更安静的音乐。';action={type:'volume',value:Math.max(.05,audio.volume*.7)}}else if(/节奏.*快|提速/.test(text)){reply='试试更明快的音乐场景。';action={type:'scene',scene:'energy'}}else if(/睡|晚安/.test(text)){reply='今天辛苦了，让柔和的声音陪你慢慢休息。';action={type:'sleep',minutes:minutes||30}}else if(/专注|工作|学习|写作/.test(text)){reply='好，把注意力留给眼前这一件事。';action={type:'focus',minutes:minutes||25}}else if(/运动|提神|能量|跑步/.test(text)){reply='给这一刻添一点轻快的节奏。';action={type:'scene',scene:'energy'}}else if(/累|放松|烦|难过|安静/.test(text)){reply='先不用急着调整自己，留一会儿，慢慢呼吸。';action={type:'scene',scene:'relax'}}else if(/播放|继续/.test(text)){reply='让声音继续陪你。';action={type:'play'}}reply+='\n（本机演示）'}const result=await runAction(action);pending.querySelector('p').textContent=reply+(result?'\n\n'+result:'');chatHistory.push({role:'assistant',content:reply});speak(reply);tick()}catch(e){pending.querySelector('p').textContent='这次没有完成：'+e.message;chatHistory.pop()}finally{busy=false;$('#send').disabled=false}}
$('#chatForm').onsubmit=e=>{e.preventDefault();const value=$('#chatInput').value;if(value.trim()&&!busy){$('#chatInput').value='';sendChat(value)}};$('#chatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#chatForm').requestSubmit()}};$$('[data-prompt]').forEach(b=>b.onclick=()=>sendChat(b.dataset.prompt));
const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;let recognition,holding=false,transcript='';if(SpeechRecognition){recognition=new SpeechRecognition();recognition.lang='zh-CN';recognition.interimResults=true;recognition.continuous=true;recognition.onresult=e=>{transcript=Array.from(e.results).map(r=>r[0].transcript).join('');$('#chatInput').value=transcript};recognition.onerror=e=>{holding=false;$('#mic').classList.remove('recording');toast('语音识别不可用（'+e.error+'），请用文字输入')};recognition.onend=()=>{holding=false;$('#mic').classList.remove('recording');if(transcript.trim()){const t=transcript;transcript='';$('#chatInput').value='';sendChat(t)}};$('#mic').onpointerdown=e=>{if(busy)return;e.preventDefault();holding=true;transcript='';$('#mic').setPointerCapture(e.pointerId);try{recognition.start();$('#mic').classList.add('recording');toast('正在听，松开后发送')}catch{holding=false}};const stop=()=>{if(holding){holding=false;recognition.stop();$('#mic').classList.remove('recording')}};$('#mic').onpointerup=stop;$('#mic').onpointercancel=stop}else{$('#mic').onclick=()=>toast('当前浏览器不支持语音识别，请使用文字，或尝试 Chrome / Edge')}
$('#clearChat').onclick=()=>{chatHistory=[];$('#messages').innerHTML='';message('assistant','对话已清空。此刻想听些什么？');toast('对话已清空')};$('#clearData').onclick=()=>{modal('清除本机数据',`<p>将删除此浏览器中的偏好、日程、反馈、连接地址和导入音频，且无法恢复。</p><button class="danger" id="confirmClear">确认清除并重新开始</button>`);$('#confirmClear').onclick=async()=>{audio.pause();const db=await dbPromise;if(db){await new Promise((resolve,reject)=>{const tx=db.transaction('tracks','readwrite');tx.objectStore('tracks').clear();tx.oncomplete=resolve;tx.onerror=reject}).catch(()=>{})}Object.keys(localStorage).filter(k=>k.startsWith('sonora:')).forEach(k=>localStorage.removeItem(k));location.reload()}};
