if('mediaSession' in navigator){for(const [action,fn] of Object.entries({play:startPlay,pause:()=>audio.pause(),previoustrack:()=>next(-1),nexttrack:()=>next()})){try{navigator.mediaSession.setActionHandler(action,fn)}catch{}}}
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();audio.paused?startPlay():audio.pause()}});
